import base64
from PyQt5.QtGui import QPixmap, QIcon

def AssetImageLoader(image_name, iconMode = False):
    dictImages = {
        'commandBlock.png':''
    }
    image_data = base64.b64decode(dictImages[image_name])
    pixmap = QPixmap()
    pixmap.loadFromData(image_data)
    if iconMode:
        return QIcon(pixmap)
    else:
        return pixmap